window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1f0187110109f10d"]={"versions": [{"id": "FIG-1f0187110109f10d", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts des AUTOSAR E2E Profile 4 Protection-Algorithmus (<code>E2E_P04Protect()</code>). Das Diagramm veranschaulicht innerhalb der E2E-Bibliothek (Classic sowie Adaptive Platform) die Serialisierung der Konfigurations-ID in das zu übertragende Daten-Array.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext-Aktion: <code>E2E_P04Protect()</code> (oben links als aufrufende Aktivität referenziert).</li>\n<li>Startknoten (Initial Node): Ausgefüllter schwarzer Kreis.</li>\n<li>Ablaufschritt / Aktion: <code>Copy 4-byte Config-&gt;DataID to bytes Data[Offset+4...Offset+7] in Big Endian order</code> (abgerundetes Rechteck).</li>\n<li>Endknoten (Activity Final Node): Ausgefüllter schwarzer Kreis mit Einfassung.</li>\n<li>Datenobjekte und Parameter: Konfigurationsstruktur <code>Config</code> mit dem 4 Byte großen Bezeichner <code>DataID</code>, Byte-Array <code>Data[]</code> sowie der Indexverschiebung <code>Offset</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Startknoten führt der Kontrollfluss direkt über eine Transition zur Aktion.</li>\n<li>In der Aktion werden 4 Bytes aus <code>Config-&gt;DataID</code> in Big-Endian-Byte-Reihenfolge in das Pufferarray <code>Data</code> an die Byte-Positionen <code>Offset+4</code> bis <code>Offset+7</code> geschrieben.</li>\n<li>Nach Abschluss des Schreibvorgangs geht der Kontrollfluss unmittelbar in den Endknoten der Aktivität über.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß AUTOSAR PRS E2E Protocol ([PRS_E2E_00366]) ist das Einbetten der Data-ID an genau dieser relativen Byte-Position (<code>Offset+4...Offset+7</code>) und in Big-Endian-Reihenfolge normativ vorgeschrieben. Implementierer müssen sicherstellen, dass die Zielplattform bei Konvertierung der 32-Bit-Konfigurationskonstante <code>DataID</code> die korrekte Netzwerk-Byte-Reihenfolge einhält und das Daten-Array eine ausreichende Puffergröße für den Zugriff bis <code>Offset+7</code> bereitstellt.</p>"}, {"id": "FIG-fea1ed5f89fdef2a", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts des AUTOSAR E2E Profile 4 Protection-Algorithmus (<code>E2E_P04Protect()</code>). Das Diagramm veranschaulicht innerhalb der E2E-Bibliothek (Classic sowie Adaptive Platform) die Serialisierung der Konfigurations-ID in das zu übertragende Daten-Array.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext-Aktion: <code>E2E_P04Protect()</code> (oben links als aufrufende Aktivität referenziert).</li>\n<li>Startknoten (Initial Node): Ausgefüllter schwarzer Kreis.</li>\n<li>Ablaufschritt / Aktion: <code>Copy 4-byte Config-&gt;DataID to bytes Data[Offset+4...Offset+7] in Big Endian order</code> (abgerundetes Rechteck).</li>\n<li>Endknoten (Activity Final Node): Ausgefüllter schwarzer Kreis mit Einfassung.</li>\n<li>Datenobjekte und Parameter: Konfigurationsstruktur <code>Config</code> mit dem 4 Byte großen Bezeichner <code>DataID</code>, Byte-Array <code>Data[]</code> sowie der Indexverschiebung <code>Offset</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Startknoten führt der Kontrollfluss direkt über eine Transition zur Aktion.</li>\n<li>In der Aktion werden 4 Bytes aus <code>Config-&gt;DataID</code> in Big-Endian-Byte-Reihenfolge in das Pufferarray <code>Data</code> an die Byte-Positionen <code>Offset+4</code> bis <code>Offset+7</code> geschrieben.</li>\n<li>Nach Abschluss des Schreibvorgangs geht der Kontrollfluss unmittelbar in den Endknoten der Aktivität über.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß AUTOSAR PRS E2E Protocol ([PRS_E2E_00366]) ist das Einbetten der Data-ID an genau dieser relativen Byte-Position (<code>Offset+4...Offset+7</code>) und in Big-Endian-Reihenfolge normativ vorgeschrieben. Implementierer müssen sicherstellen, dass die Zielplattform bei Konvertierung der 32-Bit-Konfigurationskonstante <code>DataID</code> die korrekte Netzwerk-Byte-Reihenfolge einhält und das Daten-Array eine ausreichende Puffergröße für den Zugriff bis <code>Offset+7</code> bereitstellt.</p>"}], "trans": [{"from": "FIG-1f0187110109f10d", "to": "FIG-fea1ed5f89fdef2a", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
